import { test, expect } from "@playwright/test";
import { readFile } from "node:fs/promises";
// Real official API records → parser → isolated test Postgres → anon SELECT snapshot.
// Generated by test:monitor, not synthetic contracts and not production Supabase.
test("real monitor publications, filters, 39-cell coverage, news and mobile", async ({
  page,
}) => {
  const errors: string[] = [];
  page.on("pageerror", (e) => errors.push(e.message));
  const snapshot = JSON.parse(
    await readFile("work/monitor/test-public.json", "utf8"),
  ) as Record<string, Record<string, unknown>[]>;
  let failMonitor = false;
  await page.route("http://127.0.0.1:54321/**", async (route) => {
    const u = new URL(route.request().url());
    const table = u.pathname.split("/").pop() ?? "";
    if (route.request().method() === "OPTIONS")
      return route.fulfill({
        status: 204,
        headers: {
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Headers": "*",
          "Access-Control-Allow-Methods": "GET,POST,OPTIONS",
        },
      });
    if (failMonitor && table.startsWith("monitor_"))
      return route.fulfill({
        status: 503,
        json: { message: "TEST outage" },
        headers: { "Access-Control-Allow-Origin": "*" },
      });
    return route.fulfill({
      json: snapshot[table] ?? [],
      headers: { "Access-Control-Allow-Origin": "*" },
    });
  });
  await page.goto("http://127.0.0.1:5183/#monitor");
  await expect(
    page.getByText("В загруженной выборке: 16 записей", { exact: false }),
  ).toBeVisible();
  await page
    .getByLabel("Материал монитора", { exact: true })
    .selectOption("tungsten");
  await page
    .getByLabel("Регион монитора", { exact: true })
    .selectOption("Европа");
  await expect(
    page.getByText(
      "Supply of Spherical Tungsten Powder to the University of Birmingham",
      { exact: true },
    ),
  ).toBeVisible();
  await expect(page.getByText("30 266,39", { exact: false })).toBeVisible();
  const downloadPromise = page.waitForEvent("download");
  await page
    .getByRole("button", { name: "Экспорт событий CSV", exact: true })
    .click();
  const download = await downloadPromise;
  const csv = await readFile((await download.path())!, "utf8");
  expect(csv).toContain("30266.39");
  expect(csv).toContain("7c647f54-d021-45c0-8e39-42091875789f");
  await page.getByText("Поля документа и ограничения", { exact: true }).click();
  await expect(
    page.getByText("Поставщик: ACANTECS LIMITED.", { exact: false }),
  ).toBeVisible();
  await page
    .getByRole("button", { name: "Контрактные цены", exact: true })
    .click();
  await expect(
    page.getByText("Нет контрактных цен с подтверждённым", { exact: false }),
  ).toBeVisible();
  await page
    .getByRole("button", { name: "Покрытие 13 × 3", exact: true })
    .click();
  await expect(page.locator("tbody tr")).toHaveCount(13);
  await expect(page.locator("tbody td")).toHaveCount(39);
  await expect(
    page.getByRole("cell", { name: "Источник не подключён", exact: true }),
  ).toHaveCount(13);
  await page.setViewportSize({ width: 390, height: 844 });
  await expect(
    page.getByText("Покрытие источниками, не котировками"),
  ).toBeVisible();
  expect(
    await page.evaluate(
      () => document.documentElement.scrollWidth <= window.innerWidth,
    ),
  ).toBe(true);
  await page.goto("http://127.0.0.1:5183/#news");
  await page
    .getByLabel("Категория новостей", { exact: true })
    .selectOption("tenders");
  await page.getByLabel("Период новостей", { exact: true }).selectOption("0");
  await expect(
    page.getByRole("heading", { name: "ALFA MARKET MONITOR", exact: true }),
  ).toBeVisible();
  await expect(
    page.getByText("В загруженной выборке: 16 записей", { exact: false }),
  ).toBeVisible();
  failMonitor = true;
  await page
    .getByRole("button", { name: "Обновить монитор", exact: true })
    .click();
  await expect(
    page.getByText("Ниже сохранена последняя успешно полученная выборка", {
      exact: false,
    }),
  ).toBeVisible();
  await expect(
    page.getByText("В загруженной выборке: 16 записей", { exact: false }),
  ).toBeVisible();
  expect(errors).toEqual([]);
});
